class SyncService {
    fun bad(): String {
        var localVar = "start"

        synchronized(this) {
            localVar = "updated"
        }
        return localVar
    }
}

class SyncService {
    private val lock = Any()

    fun bad(localMap: MutableMap<String, String>) {
        synchronized(lock) {
            val copy = localMap
            copy.clear()
        }
    }
}

class SyncService {
    private var sharedField = ""

    fun good(newValue: String) {
        synchronized(this) {
            sharedField = newValue
        }
    }
}

class SyncService {
    private val lock = Any()
    private val sharedList = mutableListOf<String>()

    fun good(item: String) {
        synchronized(lock) {
            sharedList.add(item)
        }
    }
}
